<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\Theme\Domain\ValueObject;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class ThemeIsDefaultVO
{
  public static function empty(): ThemeIsDefaultVO
  {
      return new ThemeIsDefaultVO(null);
  }
  public static function from(ThemeIsDefaultVO|bool|null $value): ThemeIsDefaultVO
  {
    return self::fromUnsafe($value);
  }
  public static function tryFrom(mixed $value, ConstraintFailList $list): ?ThemeIsDefaultVO
  {
    if ( $value instanceof ThemeIsDefaultVO ) {
      // If is a ValueObject, its already validated... nothing to append
      return $value;
    } else if( !$value ) {
      return new ThemeIsDefaultVO($value);
    } else if( is_bool($value)) {
      return new ThemeIsDefaultVO($value);
    } else {
      $list->add(new ConstraintFail('wrong_type', ['isDefault'], [$value], ['bool']));
      return null;
    }
  }
  private static function fromUnsafe(mixed $value): ThemeIsDefaultVO
  {
    if ($value instanceof ThemeIsDefaultVO) {
      // If is a ValueObject, its already validated
      return $value;
    } else {
      // If is not a ValueObject, validation is need and exception throw
      $errorsList = new ConstraintFailList();
      $candidate = self::tryFrom($value, $errorsList);
      if ($errorsList->hasErrors()) {
        throw $errorsList->asConstraintException();
      }
      \assert($candidate instanceof ThemeIsDefaultVO);
      return $candidate;
    }
  }
  /**
   * private constructor to avoid build a value without all the rule validations.
   */
  private function __construct(
    private readonly ?bool $isDefault
  ) {
  }
  public function value(): ?bool
  {
    return $this->isDefault;
  }
  public function equals(?ThemeIsDefaultVO $other): bool
  {
    return $this->value() == $other?->value();
  }
}
